 void refresh(){if(dead||session==null)return;
  if(android.os.Looper.myLooper()!=android.os.Looper.getMainLooper()){note("refresh from a background thread",new Throwable());runOnUiThread(this::refresh);return;}
  trail("page "+screen);
  if(content instanceof SafeFrame&&(((SafeFrame)content).measuring||((SafeFrame)content).removing||content.isInLayout())){note("refresh while measuring",new Throwable());handler.post(this::refresh);return;}projectName.setText(session.title);tempo.setText(session.timeSignature+"/4 · "+session.bpm+" BPM");loop.setSelected(engine.loop);click.setSelected(engine.click);loop.setBackground(round(engine.loop?0xffffa726:0xff20242d,14));loop.setTextColor(engine.loop?0xff1a1205:0xffe8ebf1);click.setTextColor(engine.click?0xffffa726:DIM);for(int i=0;i<navigation.getChildCount();i++){Button tab=(Button)navigation.getChildAt(i);tab.setSelected(screen.equals(tab.getTag())||(screen.equals("SAMPLES")&&"INSTRUMENT".equals(tab.getTag())));tab.setTextColor(tab.isSelected()?0xffffa726:(tab instanceof TabKey&&((TabKey)tab).icon==5?0xff9d8cff:DIM));tab.invalidate();}content.removeAllViews();timeline=null;mixer=null;eqGraph=null;reductionMeter=null;updateInspector();updateEditKeys();if(screen.equals("ARRANGE")){timeline=new Timeline();try{trackHeightDp=Math.max(60,Math.min(152,getPreferences(MODE_PRIVATE).getInt("trackHeight",88)));timeline.row=dp(trackHeightDp);}catch(Exception ignored){};content.addView(timeline);}else if(screen.equals("MIXER")){mixer=new Mixer();content.addView(mixer);}else if(screen.equals("FX"))showFx();else if(screen.equals("SAMPLES"))showSampleBrowser();else showInstruments();updateTransport();}
 void updateTransport(){if(session==null)return;long pos=engine.position;clock.setText(engine.countInRemaining>0?"COUNT "+CountIn.number(engine.countInTotal-engine.countInRemaining,session.bpm,engine.countInBeats)+" / "+engine.countInBeats:pro.clock(pos).replace(" : ",":"));play.setText(engine.playing?"Ⅱ":"▶");boolean rec=midiTake!=null||capture!=null&&capture.running;loop.setEnabled(!working&&midiTake==null&&capture==null);record.setText(rec?"■":"●");record.setActivated(rec);play.setSelected(engine.playing);record.invalidate();long millis=pos*1000/Core.RATE;timeDetail.setText(String.format(Locale.US,"%02d:%02d.%03d",millis/60000,(millis/1000)%60,millis%1000));}
