 static final int KEEP_BACKUPS=5;static final long BACKUP_EVERY=24L*3600*1000;
 String backupKey(){return "backupAt:"+(session==null?"":session.directory);}
 void autoBackupDialog(){android.content.SharedPreferences sp=getPreferences(MODE_PRIVATE);String tree=sp.getString("backupTree",null);long at=sp.getLong(backupKey(),0);
  String status=tree==null?"Off. Choose a folder (for example on Google Drive) and the app backs up each project you work on once a day, keeping the last "+KEEP_BACKUPS+" copies, including all audio.":"On. Folder: "+Uri.parse(tree).getLastPathSegment()+"\nThis project last backed up: "+(at==0?"never":new java.text.SimpleDateFormat("d MMM yyyy, HH:mm",Locale.getDefault()).format(new java.util.Date(at)))+"\nKeeps the last "+KEEP_BACKUPS+" daily copies of each project.";
  AlertDialog.Builder b=new AlertDialog.Builder(this).setTitle("Automatic backups").setMessage(status).setNegativeButton("Close",null).setPositiveButton(tree==null?"Choose folder":"Change folder",(d,w)->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);try{startActivityForResult(i,71);}catch(Exception e){error("Automatic backups",e.getMessage());}});
  if(tree!=null)b.setNeutralButton("Back up now",(d,w)->autoBackup(true));b.show();}
 /** Once a day per project (or now when forced): write a dated .acstudio into the chosen folder in the background and keep the newest copies. */
 void autoBackup(boolean force){final android.content.SharedPreferences sp=getPreferences(MODE_PRIVATE);final String tree=sp.getString("backupTree",null);if(tree==null||session==null||session.directory==null)return;final String key=backupKey();long last=sp.getLong(key,0);if(!force&&System.currentTimeMillis()-last<BACKUP_EVERY)return;
  final Core.Session snapshot;synchronized(session){snapshot=session.copy();}final String base=(snapshot.title==null||snapshot.title.trim().isEmpty()?"Project":snapshot.title).replaceAll("[^a-zA-Z0-9 _-]","").trim();sp.edit().putLong(key,System.currentTimeMillis()).apply();
  new Thread(()->{try{Uri root=Uri.parse(tree);android.content.ContentResolver cr=getContentResolver();Uri dir=android.provider.DocumentsContract.buildDocumentUriUsingTree(root,android.provider.DocumentsContract.getTreeDocumentId(root));
   String name=base+" "+new java.text.SimpleDateFormat("yyyy-MM-dd HHmm",Locale.US).format(new java.util.Date())+".acstudio";Uri doc=android.provider.DocumentsContract.createDocument(cr,dir,"application/zip",name);if(doc==null)throw new IOException("The backup folder could not be written.");
   try(OutputStream out=cr.openOutputStream(doc,"wt")){if(out==null)throw new IOException("The backup folder could not be written.");AudioIO.backup(out,snapshot);}
   Uri children=android.provider.DocumentsContract.buildChildDocumentsUriUsingTree(root,android.provider.DocumentsContract.getTreeDocumentId(root));ArrayList<String[]> mine=new ArrayList<>();
   try(android.database.Cursor c=cr.query(children,new String[]{android.provider.DocumentsContract.Document.COLUMN_DOCUMENT_ID,android.provider.DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){while(c!=null&&c.moveToNext()){String n=c.getString(1);if(n!=null&&n.startsWith(base+" ")&&n.endsWith(".acstudio")&&n.length()==base.length()+1+15+9)mine.add(new String[]{c.getString(0),n});}}
   java.util.Collections.sort(mine,(x,y)->x[1].compareTo(y[1]));for(int i=0;i<mine.size()-KEEP_BACKUPS;i++)try{android.provider.DocumentsContract.deleteDocument(cr,android.provider.DocumentsContract.buildDocumentUriUsingTree(root,mine.get(i)[0]));}catch(Exception ignored){}
   if(force)runOnUiThread(()->toast("Backup saved: "+name));
  }catch(Exception e){sp.edit().putLong(key,0).apply();if(force)runOnUiThread(()->error("Automatic backup",e.getMessage()==null?"Backup failed.":e.getMessage()));}},"CityStudio-AutoBackup").start();}
 void menu(){if(!canEdit())return;String[] options={"Save project","Open project","New empty project","Load demo as new project","Export (WAV, FLAC, AAC, stems)…","Undo last clip edit","Rename project","Track settings","Help & build status","Back up project (.acstudio)","Restore project backup","Redo last edit","Sample licences & credits","MIDI controller input","Export MIDI performance (.mid)","Pro tools…","Repair clip spacing & lengths","Automatic backups…","Recording timing & quantize…"};new AlertDialog.Builder(this).setTitle("Audio City Studio").setItems(options,(d,i)->{switch(i){case 0:save(true);break;case 1:openProject();break;case 2:engine.stop();save(false);busy("Creating project…",()->{Core.Session s=emptySession();AudioIO.save(s);runOnUiThread(()->bind(s));});break;case 3:engine.stop();save(false);busy("Building demo…",()->{Core.Session s=demoSession();runOnUiThread(()->bind(s));});break;case 4:export();break;case 5:undo();break;case 6:renameProject();break;case 7:trackSettings();break;case 8:help();break;case 9:backup();break;case 10:restore();break;case 11:redoEdit();break;case 12:sampleCredits();break;case 13:midiDialog();break;case 14:exportMidi();break;case 15:pro.menu();break;case 16:repairPatternSpacing();break;case 17:autoBackupDialog();break;case 18:recordingOptions();break;}}).show();}
 void repairPatternSpacing(){if(!canEdit())return;engine.pause();try{Core.Session before;int count,melodies=0;synchronized(session){before=session.copy();count=PatternArrangement.repairOverlaps(session);for(Core.Track track:session.tracks)for(Core.Clip item:track.clips)if(ProMidi.trimRecordedEmptyEnd(session,item))melodies++;}if(count==0&&melodies==0){toast("No overlapping pattern copies or empty recorded melody ends found.");return;}undo.addLast(before);pro.history.put(before,"Repair clip spacing and lengths");while(undo.size()>50)undo.removeFirst();redo.clear();save(false);refresh();toast(count+" pattern clips re-spaced; "+melodies+" recorded clips shortened to their last note's bar. Undo is available.");}catch(Exception error){error("Clip spacing and lengths",error.getMessage());}}

