 void tempoDialog(){if(!canEdit())return;LinearLayout box=column();box.setPadding(dp(18),dp(8),dp(18),dp(8));EditText value=numberField(box,"NEW PROJECT TEMPO / 40–240 BPM",String.valueOf(session.bpm));RadioGroup mode=new RadioGroup(this);for(String label:new String[]{"Time-stretch all audio · keep pitch","Resample all audio · pitch changes","Grid only · leave audio unchanged"}){RadioButton button=new RadioButton(this);button.setText(label);button.setTextSize(12);button.setId(View.generateViewId());mode.addView(button);}mode.check(mode.getChildAt(0).getId());box.addView(mode);box.addView(label("Time stretch retimes source audio and region positions. Large changes can cause artifacts; pitch-preserving changes support 0.5×–2× per step.",11,DIM,false));new AlertDialog.Builder(this).setTitle("Change project tempo").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Apply tempo",(d,w)->{try{int bpm=Integer.parseInt(value.getText().toString());if(bpm<40||bpm>240)throw new NumberFormatException();if(bpm==session.bpm)return;int option=mode.indexOfChild(mode.findViewById(mode.getCheckedRadioButtonId()));engine.pause();checkpoint();if(option==2){session.bpm=bpm;save(false);refresh();return;}Core.Session original=session.copy();long cursor=engine.position;int selectedIndex=session.tracks.indexOf(selected);busy("Retiming project audio…",()->{Core.Session updated=AudioIO.retimeProject(original,bpm,option==0);runOnUiThread(()->{session=updated;selected=selectedIndex>=0&&selectedIndex<updated.tracks.size()?updated.tracks.get(selectedIndex):null;clip=null;engine.position=Math.round(cursor*original.bpm/(double)bpm);save(false);refresh();toast("Project audio and clip positions retimed to "+bpm+" BPM.");});});}catch(NumberFormatException e){toast("Use an integer tempo between 40 and 240 BPM.");}}).show();}
 void addTrack(){if(!canEdit())return;if(session.tracks.size()>=Core.MAX_TRACKS){toast("This build supports "+Core.MAX_TRACKS+" tracks.");return;}input("New audio track","Audio "+(session.tracks.size()+1),false,s->{checkpoint();Core.Track t=new Core.Track(s.trim().isEmpty()?"Audio":s.trim(),COLORS[session.tracks.size()%COLORS.length]);session.tracks.add(t);selected=t;clip=null;refresh();save(false);});}
 void trackSettings(){if(selected==null)return;final Core.Track t=selected;String[] base={"Rename track","Open effects","Remove track from project","Change instrument…"},extra=pro.trackItems(t),items=new String[base.length+extra.length];System.arraycopy(base,0,items,0,base.length);System.arraycopy(extra,0,items,base.length,extra.length);new AlertDialog.Builder(this).setTitle(t.name).setItems(items,(d,i)->{if(i==3){pro.chooseTrackInstrument(t);return;}if(i>=4){pro.trackItem(t,i-4);return;}if(i==0)input("Track name",t.name,false,n->{checkpoint();t.name=n.trim().isEmpty()?"Audio":n.trim();save(false);refresh();});else if(i==1){screen="FX";refresh();}else new AlertDialog.Builder(this).setTitle("Remove track?").setMessage("This removes the track from this project. Source audio is kept; Undo can restore the edit.").setNegativeButton("Cancel",null).setPositiveButton("Remove",(dd,w)->{engine.pause();checkpoint();session.tracks.remove(t);selected=session.tracks.isEmpty()?null:session.tracks.get(0);clip=null;save(false);refresh();}).show();}).show();}
