 /** After importing a loop: show its detected tempo and offer to conform it to the project tempo. */
 void offerTempoMatch(Core.Session project,Core.Track track,Core.Clip imported,float[] pcm,LoopTempo.Result guess){
  if(session!=project||dead)return;
  if(Math.abs(guess.bpm-project.bpm)<.3){toast("Loop is already at "+project.bpm+" BPM.");return;}
  LinearLayout box=column();box.setPadding(dp(20),dp(8),dp(20),0);
  box.addView(label((guess.bars>0||guess.fromName?"Loop tempo: ":"Possible tempo: ")+LoopTempo.describe(guess),15,TEXT,true));
  box.addView(label("Project tempo: "+project.bpm+" BPM. Matching changes the loop's speed without changing its pitch. Edit the loop tempo if it's wrong.",12,DIM,false));
  final EditText field=new EditText(this);field.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);field.setText(String.format(Locale.US,"%.1f",guess.bpm));field.setSelectAllOnFocus(true);box.addView(field);
  new AlertDialog.Builder(this).setTitle("Match loop to project tempo?").setView(box)
   .setPositiveButton("Match "+project.bpm+" BPM",(d,w)->{double src;try{src=Double.parseDouble(field.getText().toString().trim());}catch(Exception e){toast("Enter the loop's tempo in BPM.");return;}conformLoop(project,track,imported,pcm,src);})
   .setNegativeButton("Keep original",null).show();
 }
 void conformLoop(Core.Session project,Core.Track track,Core.Clip imported,float[] pcm,double sourceBpm){
  if(sourceBpm<40||sourceBpm>260){toast("Loop tempo must be between 40 and 260 BPM.");return;}
  final int target=LoopTempo.targetFrames(pcm.length/2,sourceBpm,project.bpm);double ratio=target/(pcm.length/2.0);
  if(ratio<.5||ratio>2){toast("That tempo change is too large to sound good. Try a half- or double-time tempo.");return;}
  if(target>Core.RATE*90){toast("The matched loop would be longer than 90 seconds; kept the original.");return;}
  if(!canEdit())return;checkpoint();
  busy("Matching loop to "+project.bpm+" BPM…",()->{
   float[] out=BeatPilotLoopStretch.stretch(pcm,target);File dir=new File(project.directory);
   Core.Clip fitted=AudioIO.store(dir,out,imported.name,imported.start);
   runOnUiThread(()->{if(session!=project||!track.clips.contains(imported)){new File(dir,fitted.file).delete();toast("Project changed; loop left as it was.");return;}
    int at=track.clips.indexOf(imported);track.clips.set(at,fitted);if(imported.file!=null)new File(dir,imported.file).delete();clip=fitted;save(false);refresh();
    toast(String.format(Locale.US,"Loop matched: %.1f → %d BPM.",sourceBpm,project.bpm));});
  });
 }
