 boolean headphonesConnected(){try{AudioManager am=(AudioManager)getSystemService(AUDIO_SERVICE);for(android.media.AudioDeviceInfo d:am.getDevices(AudioManager.GET_DEVICES_OUTPUTS)){int t=d.getType();if(t==android.media.AudioDeviceInfo.TYPE_WIRED_HEADPHONES||t==android.media.AudioDeviceInfo.TYPE_WIRED_HEADSET||t==android.media.AudioDeviceInfo.TYPE_BLUETOOTH_A2DP||t==android.media.AudioDeviceInfo.TYPE_USB_HEADSET||(Build.VERSION.SDK_INT>=31&&t==android.media.AudioDeviceInfo.TYPE_BLE_HEADSET))return true;}}catch(Exception ignored){}return false;}
 /** After a speaker take: render exactly what played, subtract it from the vocal, and swap in the cleaned take (Undo restores the original). */
 void removeBeatBleed(Core.Session project,Core.Track track,Core.Clip take,Core.Session played,boolean click){
  busy("Removing the beat from your vocal…",()->{
   File dir=new File(project.directory),refFile=new File(dir,"bleed-ref-"+UUID.randomUUID()+".pcm"),outFile=new File(dir,UUID.randomUUID()+".pcm");final long frames=take.length;
   try{
    Core.Renderer renderer=new Core.Renderer(played);renderer.meterLoudness=false;float[] block=new float[1024];
    try(AudioIO.Writer w=new AudioIO.Writer(refFile)){for(long p=0;p<frames;p+=512){int n=(int)Math.min(512,frames-p);renderer.render(take.start+p,n,block,click);for(int i=0;i<n;i++)w.sample(block[i*2],block[i*2+1]);}}
    final Core.Source ref=new AudioIO.Disk(refFile),mic=take.source;final long offset=take.offset;
    BleedRemover.Reader micReader=(f,out,n)->{for(int i=0;i<n;i++){long q=offset+f+i;boolean in=q>=0&&q<mic.frames();out[i*2]=in?mic.sample((int)q,0):0;out[i*2+1]=in?mic.sample((int)q,1):0;}};
    BleedRemover.Reader refReader=(f,out,n)->{for(int i=0;i<n;i++){long q=f+i;boolean in=q>=0&&q<ref.frames();out[i*2]=in?ref.sample((int)q,0):0;out[i*2+1]=in?ref.sample((int)q,1):0;}};
    final BleedRemover.Report report;try(AudioIO.Writer w=new AudioIO.Writer(outFile)){report=BleedRemover.process(micReader,refReader,frames,.6,(s,n)->{for(int i=0;i<n;i++)w.sample(s[i*2],s[i*2+1]);});}
    final Core.Clip cleaned=new Core.Clip(take.name,new AudioIO.Disk(outFile),outFile.getName(),take.start);cleaned.length=(int)Math.min(cleaned.length,take.length);cleaned.gain=take.gain;cleaned.fadeIn=take.fadeIn;cleaned.fadeOut=take.fadeOut;
    runOnUiThread(()->{refFile.delete();if(session!=project||!track.clips.contains(take)){outFile.delete();return;}checkpoint();int at=track.clips.indexOf(take);track.clips.set(at,cleaned);if(clip==take)clip=cleaned;save(false);refresh();toast("Beat removed from your vocal. Undo brings back the original take.");});
   }catch(Exception e){refFile.delete();outFile.delete();throw e;}
  });
 }
