 /**
  * Loopback test: plays clicks through the speaker while recording them, then measures how far from the beat the clicks
  * land in the recording. The leftover is stored and applied to every new audio recording.
  */
 void latencyTest(){
  if(!canEdit())return;if(headphonesConnected()){toast("Unplug or disconnect the headphones for this test.");return;}
  if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},31);return;}
  if(!requestAudioFocus())return;engine.pause();
  final Core.Session test=new Core.Session();test.bpm=100;test.directory=getCacheDir().getAbsolutePath();final File file=new File(getCacheDir(),"latency-test.pcm");file.delete();
  final boolean oldClick=engine.click,oldLoop=engine.loop;final long oldPos=engine.position;final float oldVolume=engine.clickVolume;
  final AudioIO.Capture probe=new AudioIO.Capture();final long beatF=Core.beat(test.bpm);
  toast("Measuring… keep quiet for 3 seconds.");
  probe.begin(file,()->runOnUiThread(()->{
   final long first=probe.firstFrameNanos>0&&engine.clockRunning()?engine.heardAt(probe.firstFrameNanos):Long.MIN_VALUE;
   engine.pause();engine.recording=false;engine.click=oldClick;engine.loop=oldLoop;engine.position=oldPos;engine.clickVolume=oldVolume;
   if(probe.error!=null||first==Long.MIN_VALUE){toast("The test could not record. Try again.");return;}
   busy("Measuring the delay…",()->{
    AudioIO.Disk d=new AudioIO.Disk(file);int n=d.frames();float[] env=new float[n];for(int i=0;i<n;i++)env[i]=Math.abs(d.sample(i,0));
    float peak=0;for(float v:env)peak=Math.max(peak,v);if(peak<.01f)throw new java.io.IOException("I couldn't hear the clicks. Turn the volume up and try again.");
    ArrayList<Long> errors=new ArrayList<>();int i=0;
    while(i<n){if(env[i]>peak*.4f){long song=first+i,beat=Math.round(song/(double)beatF)*beatF;if(beat>0)errors.add(song-beat);i+=(int)(beatF/2);}else i++;}
    if(errors.size()<3)throw new java.io.IOException("Too few clicks were heard. Turn the volume up and try again.");
    Collections.sort(errors);final long residual=errors.get(errors.size()/2);
    runOnUiThread(()->{long trim=engine.latencyTrim+residual;if(Math.abs(trim)>Core.RATE/2){toast("That measurement looks wrong ("+Math.round(trim*1000.0/Core.RATE)+" ms). Try again in a quiet room.");return;}
     engine.latencyTrim=trim;getPreferences(MODE_PRIVATE).edit().putLong("latencyTrim",trim).apply();
     new AlertDialog.Builder(this).setTitle("Recording timing measured").setMessage("Recordings will be shifted "+Math.round(trim*1000.0/Core.RATE)+" ms so they land exactly on the beat."+(engine.clockFromHardware?"":"\n\nThis phone does not report exact audio timestamps, so this correction matters. Repeat the test if you change headphones or audio devices.")).setPositiveButton("OK",null).show();});
    file.delete();
   });
  }));
  handler.postDelayed(()->{if(!probe.running){toast("The microphone did not start.");return;}engine.click=true;engine.clickVolume=1.6f;engine.loop=false;engine.recording=true;engine.position=0;engine.play(test);handler.postDelayed(probe::stop,3200);},350);
 }
 /** The record-enabled track (R on its channel strip), or the selected track when none is armed. */
 Core.Track recordTarget(){if(session!=null)for(Core.Track t:session.tracks)if(t.armed)return t;return selected;}
 void startCapture(){startCapture(false,false,false);}
 void startCapture(final boolean speaker,final boolean removeBleed,boolean echo){if(!canEdit()||!requestAudioFocus())return;engine.pause();engine.loop=false;checkpoint();pro.preRoll();recordStart=engine.position;final long start=recordStart;final Core.Track target=recordTarget();final Core.Session project=session;recordFile=new File(project.directory,UUID.randomUUID()+".pcm");final File file=recordFile;final AudioIO.Capture take=new AudioIO.Capture();pro.configureCapture(take,target);take.echoCancel=echo;if(speaker){android.content.SharedPreferences sp=getPreferences(MODE_PRIVATE);int route=sp.getInt("speakerRoute",0);take.cameraMic=sp.getInt("speakerMic",0)==1;if(route==3){android.media.AudioDeviceInfo ear=SpeakerTest.earpiece(this);if(ear!=null)AudioIO.Output.preferred=ear;else route=0;}engine.speakerRoute=route;}final Core.Session played=removeBleed?project.copy():null;final boolean clickOn=engine.click;if(speaker)engine.outputGain=.5f;capture=take;captureStarted=System.nanoTime();engine.recording=true;take.begin(file,()->runOnUiThread(()->{stopRecordingService();engine.outputGain=1f;engine.speakerRoute=0;AudioIO.Output.preferred=null;engine.recording=false;engine.monitor=null;engine.monitorTrack=null;engine.pause();capture=null;if(dead)return;if(take.error!=null){error("Recording",take.error);}final long measuredFirst=take.firstFrameNanos>0&&engine.clockRunning()?engine.heardAt(take.firstFrameNanos)-engine.latencyTrim:start,heardFirst=Math.abs(measuredFirst-start)>Core.RATE*3L?start:measuredFirst;if(file.length()>=8){busy("Preparing recorded take…",()->{Core.Clip c=new Core.Clip("Take "+(target.clips.size()+1),new AudioIO.Disk(file),file.getName(),start);
  // Latency compensation: the first microphone frame belongs where the song was being heard at that instant.
  long[] where=TransportClock.place(start,heardFirst,c.length);int early=(int)where[1];if(early>0){c.offset=early;c.envelopeOffset=early;c.length-=early;}long placed=where[0];c.start=placed;
  c.length=(int)Math.max(1,Math.min(c.length,Core.MAX_FRAMES-placed));runOnUiThread(()->{if(c.length>0){pro.afterRecording(target,c,take);target.clips.add(c);clip=c;}save(false);refresh();if(c.length>0&&played!=null)removeBeatBleed(project,target,c,played,clickOn);});});}else toast("No audio was recorded.");}));engine.play(session);startRecordingService(target.name);refresh();}
 void split(){if(!canEdit()||selected==null||clip==null){toast("Select a clip, then position the playhead inside it using the ruler.");return;}long at=engine.position,delta=at-clip.start;if(delta<1||delta>=clip.length){toast("Place the playhead inside the selected clip.");return;}engine.pause();checkpoint();Core.Clip right=clip.copy();right.name=clip.name+" · B";right.start=at;right.offset+=(int)delta;right.envelopeOffset+=(int)delta;right.length-=(int)delta;clip.length=(int)delta;selected.clips.add(right);clip=right;save(false);refresh();}
 void clipMenu(Core.Track t,Core.Clip c){if(!canEdit())return;selected=t;clip=c;new AlertDialog.Builder(this).setTitle(c.name).setItems(new String[]{"Rename clip","Move to bar…","Trim audio…","Duplicate after clip","Remove clip (Undo available)","Clip gain & fades","Pitch correct vocal region","Restore preserved dry vocal","Pro clip tools (takes, slip, ripple, piano roll)…"},(d,i)->{if(i==8){pro.clipTools(t,c);return;}if(i==0)input("Clip name",c.name,false,s->{checkpoint();c.name=s;refresh();save(false);});if(i==1)input("Start bar · 1 or later",String.format(Locale.US,"%.2f",c.start/(Core.beat(session.bpm)*4.0)+1),true,s->{double bar=Double.parseDouble(s);long at=Core.snap((long)((bar-1)*Core.beat(session.bpm)*4),session.bpm,session.snapDivision);if(bar<1||at+c.length>Core.MAX_FRAMES)throw new IllegalArgumentException("Clip must fit within the 60-minute session.");checkpoint();c.start=at;save(false);refresh();});if(i==2)trim(c);if(i==3){if(c.start+2L*c.length>Core.MAX_FRAMES){toast("Clip exceeds the 60-minute session limit.");return;}checkpoint();Core.Clip copy=c.copy();copy.start+=c.length;t.clips.add(copy);clip=copy;save(false);refresh();}if(i==4){checkpoint();t.clips.remove(c);clip=null;save(false);refresh();}if(i==5)clipProperties(c);if(i==6)pitchCorrectionDialog();if(i==7)restoreDryVocal(t,c);}).show();}
 void trim(Core.Clip c){LinearLayout box=column();box.setPadding(dp(20),dp(8),dp(20),0);TextView hint=label("Times are measured within the original source audio.",13,DIM,false);box.addView(hint);EditText from=new EditText(this),to=new EditText(this);from.setInputType(8194);to.setInputType(8194);from.setHint("Start seconds");to.setHint("End seconds");from.setText(String.format(Locale.US,"%.3f",c.offset/(double)Core.RATE));to.setText(String.format(Locale.US,"%.3f",(c.offset+c.length)/(double)Core.RATE));box.addView(from);box.addView(to);new AlertDialog.Builder(this).setTitle("Trim source boundaries").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Trim",(d,w)->{try{int a=(int)(Double.parseDouble(from.getText().toString())*Core.RATE),b=(int)(Double.parseDouble(to.getText().toString())*Core.RATE);if(a<0||b<=a||b>c.source.frames()||c.start+(long)b-a>Core.MAX_FRAMES)throw new Exception();engine.pause();checkpoint();c.offset=a;c.length=b-a;c.envelopeOffset=0;c.envelopeLength=c.length;c.fadeIn=Math.min(c.fadeIn,c.length);c.fadeOut=Math.min(c.fadeOut,c.length);save(false);refresh();}catch(Exception e){toast("Use valid start and end times within the source duration.");}}).show();}
 void help(){error("Audio City Studio · 0.13.18","New in 0.12: Vocal editor (clip menu → Pro clip tools): move each sung note's pitch, timing, drift, vibrato, level and formant, split and join notes. Also new: free CC0 loops from Freesound (sample browser → Get free loops online; needs a free Freesound API key). Also new: 11 insert effects (phaser, flanger, tremolo/auto-pan, auto-filter, drive, bitcrusher, gate, de-esser, doubler, exciter, pitch shifter). 64 audio tracks + 16 buses • 60-minute projects • 48 kHz float engine\n\nPRO TOOLS (project menu → Pro tools…): routing, sends, sidechain and fader groups; reverb/delay/group buses; insert slots with 8-band parametric EQ, 3-band multiband compressor, true-peak limiter, utility and chorus; master chain with live LUFS / true-peak metering; automation with write mode; takes & comping; slip and ripple edits; piano-roll MIDI editing; tempo changes, time signature and markers; low-latency output, input monitoring, USB interface inputs and recording-latency calibration; WAV / FLAC / AAC / stems export with loudness normalisation; undo history; project templates and channel presets. The project is saved after each edit and every minute.\n\nARRANGE: tap a track to select it. Tap the ruler to move the playhead. Swipe to scroll. Choose Move, hold a clip still for a moment, then drag it. Use Trim for edge edits; positions use Snap. Long-press a clip for trim, move, duplicate and remove. Drag empty space to scroll. −/+ zoom the grid. The scissors cut at the playhead. Delete removes the selected clip; Undo restores it. Pinch the timeline or use −/+ to zoom.\n\nMIXER: touch faders, pan controls and M/S. FX applies to the selected track. Instrument creates synthesised notes, chords and drum patterns as audio clips.\n\nProjects auto-save inside the app. WAV export is stereo 48 kHz / 16- or 24-bit with effects and sample-peak limiting. Back up project creates a portable .acstudio archive including source audio. Restore project backup opens it as a new project. Uninstalling removes internal projects; back up important work first.\n\nThis is an early working build, not a commercial-release DAW. It has no VST/AU hosting, background recording, or automatic input-latency compensation. Editable MIDI piano rolls are available from clip tools. Project length is limited to 60 minutes. It has not been tested on physical Android hardware.");}
