 class Knob extends View {final String name,unit;final double min,max;final Value value;final Paint p=new Paint(3);float down,downX,lastY;double initial;boolean moved,armed,drifted,projectEdit=true;final Runnable armRun=new Runnable(){public void run(){armed=true;down=lastY;initial=value.get();moved=false;if(getParent()!=null)getParent().requestDisallowInterceptTouchEvent(true);performHapticFeedback(android.view.HapticFeedbackConstants.LONG_PRESS);}};Knob(String n,double a,double b,String u,Value v){super(MainActivity.this);name=n;min=a;max=b;unit=u;value=v;setClickable(true);setFocusable(true);setContentDescription(n+" "+display());}String display(){double v=value.get();return unit.equals("%")?Math.round(v*100)+" %":String.format(Locale.US,"%.1f %s",v,unit);}protected void onDraw(Canvas c){float w=getWidth(),cx=w/2,cy=dp(49),r=dp(28);p.setStyle(Paint.Style.FILL);p.setColor(DIM);p.setTextAlign(Paint.Align.CENTER);p.setTypeface(Typeface.create("sans-serif-medium",0));p.setTextSize(dp(9));c.drawText(name,cx,dp(13),p);p.setColor(0xff1d2226);c.drawCircle(cx,cy+dp(3),r+dp(4),p);p.setShader(new LinearGradient(cx-r,cy-r,cx+r,cy+r,new int[]{0xffb6bdc1,0xff747f87,0xff4b555e},null,Shader.TileMode.CLAMP));c.drawCircle(cx,cy,r,p);p.setShader(null);p.setColor(0xffcbd2d6);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1));c.drawCircle(cx,cy,r,p);p.setColor(0xff535e64);p.setStrokeWidth(dp(2));RectF arc=new RectF(cx-r-dp(6),cy-r-dp(6),cx+r+dp(6),cy+r+dp(6));c.drawArc(arc,135,270,false,p);p.setColor(ACCENT);c.drawArc(arc,135,(float)(270*(value.get()-min)/(max-min)),false,p);double angle=Math.toRadians(135+270*(value.get()-min)/(max-min));p.setStrokeWidth(dp(3));p.setStrokeCap(Paint.Cap.ROUND);p.setColor(0xffecf1f3);c.drawLine(cx+(float)Math.cos(angle)*r*.55f,cy+(float)Math.sin(angle)*r*.55f,cx+(float)Math.cos(angle)*r*.85f,cy+(float)Math.sin(angle)*r*.85f,p);p.setStrokeCap(Paint.Cap.BUTT);p.setStyle(Paint.Style.FILL);p.setTextSize(dp(11));p.setColor(TEXT);c.drawText(display(),cx,dp(99),p);}
 public boolean onTouchEvent(android.view.MotionEvent e){if(working||(projectEdit&&(midiTake!=null||capture!=null)))return true;
  switch(e.getAction()){
   case 0:down=lastY=e.getY();downX=e.getX();initial=value.get();moved=false;armed=false;drifted=false;postDelayed(armRun,170);return true;
   case 2:lastY=e.getY();if(!armed){if(Math.abs(e.getY()-down)>dp(8)||Math.abs(e.getX()-downX)>dp(8)){drifted=true;removeCallbacks(armRun);}return true;}
    if(!moved&&Math.abs(e.getY()-down)>dp(4)){if(projectEdit)checkpoint();moved=true;}
    if(moved){value.set(Math.max(min,Math.min(max,initial+(down-e.getY())/dp(150)*(max-min))));setContentDescription(name+" "+display());invalidate();}return true;
   case 1:removeCallbacks(armRun);if(getParent()!=null)getParent().requestDisallowInterceptTouchEvent(false);if(moved)save(false);else if(!drifted)performClick();armed=false;return true;
   case 3:removeCallbacks(armRun);if(getParent()!=null)getParent().requestDisallowInterceptTouchEvent(false);if(moved)save(false);armed=false;return true;
  }return true;}
 public boolean performClick(){if(working||(projectEdit&&!canEdit()))return true;super.performClick();LinearLayout wrap=column();wrap.setPadding(dp(20),dp(10),dp(20),dp(10));TextView v=label(display(),18,TEXT,true);wrap.addView(v);SeekBar slider=new SeekBar(MainActivity.this);slider.setMax(1000);slider.setProgress((int)((value.get()-min)/(max-min)*1000));wrap.addView(slider);final boolean[] edited={false};slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int progress,boolean user){if(user&&!edited[0]){if(projectEdit)checkpoint();edited[0]=true;}value.set(min+(max-min)*progress/1000);v.setText(display());invalidate();}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});new AlertDialog.Builder(MainActivity.this).setTitle(name).setView(wrap).setPositiveButton("Done",(d,w)->save(false)).setOnDismissListener(d->save(false)).show();return true;}}
