 void preview(float[] samples){if(!requestAudioFocus())return;audition.stop();audition.position=0;Core.Session s=new Core.Session();Core.Track t=new Core.Track("Preview",COLORS[0]);t.clips.add(new Core.Clip("Preview",new Core.Memory(samples),"",0));s.tracks.add(t);audition.play(s);}
 void insertGenerated(String name,float[] data){if(!canEdit()||selected==null)return;audition.stop();engine.pause();final Core.Track t=selected;final long at=engine.position;if(at+data.length/2>Core.MAX_FRAMES){toast("Clip exceeds the 60-minute session limit.");return;}checkpoint();busy("Creating "+name+"…",()->{Core.Clip c=AudioIO.store(new File(session.directory),data,name,at);runOnUiThread(()->{t.clips.add(c);clip=c;screen="ARRANGE";save(false);refresh();});});}
