 class DrumGrid extends View {boolean[][] steps;String[] names;Paint p=new Paint(3);DrumGrid(boolean[][] s){this(s,new String[]{"KICK","SNARE","HAT"});}DrumGrid(boolean[][] s,String[] labels){super(MainActivity.this);steps=s;names=labels;setContentDescription("Drum sequencer. "+s.length+" lanes with sixteen steps each.");}protected void onDraw(Canvas c){float left=dp(47),w=(getWidth()-left)/16f;p.setTypeface(Typeface.create("sans-serif-medium",0));p.setTextSize(dp(9));for(int row=0;row<steps.length;row++){float y=dp(31+row*43);p.setColor(DIM);c.drawText(names[row],0,y+dp(16),p);for(int i=0;i<16;i++){p.setColor(steps[row][i]?COLORS[row]:i%4==0?0xff606a71:0xff3d464d);c.drawRoundRect(left+i*w+1,y,left+(i+1)*w-2,y+dp(31),dp(3),dp(3),p);}}for(int i=0;i<16;i++){p.setColor(DIM);c.drawText(i%4==0?String.valueOf(i/4+1):"·",left+i*w+w*.3f,dp(20),p);}}public boolean onTouchEvent(MotionEvent e){if(e.getAction()==MotionEvent.ACTION_DOWN){int row=(int)((e.getY()-dp(31))/dp(43)),step=(int)((e.getX()-dp(47))/((getWidth()-dp(47))/16f));if(e.getY()>=dp(31)&&e.getX()>=dp(47)&&row>=0&&row<steps.length&&step>=0&&step<16){steps[row][step]=!steps[row][step];invalidate();}return true;}return true;}}

 interface IndexPick{void pick(int index);}
 /** Section name for a sampled instrument, so long lists are shown grouped rather than all together. */
 static String sampleGroup(String name){String n=name==null?"":name.toLowerCase(java.util.Locale.US);if(n.contains("guitar"))return "Sampled · guitars";if(n.contains("bass"))return "Sampled · bass";if(n.contains("drum")||n.contains("perc")||n.contains("afro"))return "Sampled · drums & percussion";if(n.contains("piano")||n.contains("upright")||n.contains("grand")||n.contains("keys"))return "Sampled · pianos & keys";return "Sampled · other & imported";}
 /** Two-step picker: choose a section, then an instrument inside it. done receives the index into labels. */
 void pickGrouped(final String title,final String[] labels,final String[] groups,final IndexPick done){
  final java.util.LinkedHashMap<String,ArrayList<Integer>> map=new java.util.LinkedHashMap<>();
  for(int i=0;i<labels.length;i++){ArrayList<Integer> list=map.get(groups[i]);if(list==null){list=new ArrayList<>();map.put(groups[i],list);}list.add(i);}
  final String[] names=map.keySet().toArray(new String[0]);String[] shown=new String[names.length];
  for(int g=0;g<names.length;g++)shown[g]=names[g]+"  ("+map.get(names[g]).size()+")";
  new AlertDialog.Builder(this).setTitle(title).setItems(shown,(d,g)->{
   final ArrayList<Integer> items=map.get(names[g]);String[] rows=new String[items.size()];for(int k=0;k<rows.length;k++)rows[k]=labels[items.get(k)];
   new AlertDialog.Builder(this).setTitle(names[g]).setItems(rows,(d2,k)->done.pick(items.get(k))).setNeutralButton("‹ Sections",(d3,w)->pickGrouped(title,labels,groups,done)).setNegativeButton("Cancel",null).show();
  }).setNegativeButton("Cancel",null).show();
 }
