 void drawSamples(LinearLayout list){list.removeAllViews();String query=sampleQuery.toLowerCase(Locale.ROOT);int count=0;for(SampleBank.Entry entry:sampleBank.entries){if(!sampleCategory.equals("All")&&!entry.category.equals(sampleCategory))continue;if(!(entry.name+" "+entry.creator+" "+entry.category).toLowerCase(Locale.ROOT).contains(query))continue;count++;LinearLayout row=column();row.setPadding(dp(13),dp(12),dp(13),dp(12));row.setBackground(round(PANEL,14));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(10);list.addView(row,lp);TextView name=label("Audio City · "+entry.name,14,TEXT,true);name.setOnClickListener(v->sampleInfo(entry));row.addView(name);TextView info=label((entry.loop()?entry.bpm+" BPM · "+entry.bars+" bars":"One-shot · "+entry.category)+String.format(Locale.US," · %.2f s",entry.frames/(double)Core.RATE),11,DIM,false);info.setPadding(0,dp(5),0,dp(4));row.addView(info);TextView credit=label(entry.creator+" · "+entry.license,9,DIM,false);credit.setSingleLine();credit.setEllipsize(android.text.TextUtils.TruncateAt.END);row.addView(credit);LinearLayout actions=new LinearLayout(this);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(38));ap.topMargin=dp(9);row.addView(actions,ap);Button preview=button("▶  Audition",()->{if(!canEdit())return;rememberBankScroll();engine.pause();busy("Loading sample…",()->{float[] audio=sampleBank.load(entry);runOnUiThread(()->preview(audio));});});actions.addView(preview,new LinearLayout.LayoutParams(0,-1,1));Button insert=button("Insert on track",()->insertSample(entry));LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(0,-1,1);ip.leftMargin=dp(8);actions.addView(insert,ip);}if(count==0)list.addView(label("No samples match this search.",14,DIM,false));}
