 boolean[][] afroSteps(int preset){boolean[][] steps=new boolean[6][16];if(preset==3)return steps;for(int i:new int[]{0,6,8,11})steps[0][i]=true;steps[1][4]=steps[1][12]=true;for(int i=0;i<16;i+=2)steps[2][i]=true;for(int i:new int[]{3,7,10,15})steps[3][i]=true;for(int i:new int[]{5,13})steps[4][i]=true;for(int i=0;i<16;i++)steps[5][i]=true;if(preset==1){Arrays.fill(steps[0],false);steps[0][0]=steps[0][8]=true;Arrays.fill(steps[3],false);steps[3][6]=steps[3][14]=true;Arrays.fill(steps[4],false);steps[4][7]=steps[4][15]=true;}if(preset==2){Arrays.fill(steps[0],false);for(int i:new int[]{0,6,10})steps[0][i]=true;Arrays.fill(steps[1],false);steps[1][4]=steps[1][12]=true;for(int i=0;i<16;i++)steps[5][i]=i%2==0;}return steps;}
