 void stereoDelayControls(LinearLayout box,Core.Fx f){LinearLayout options=new LinearLayout(this);box.addView(options);Switch sync=new Switch(this);sync.setText("Tempo sync ");sync.setTextSize(11);sync.setChecked(f.delaySync);options.addView(sync,new LinearLayout.LayoutParams(0,dp(42),1));Switch ping=new Switch(this);ping.setText("Ping-pong ");ping.setTextSize(11);ping.setChecked(f.pingPong);options.addView(ping,new LinearLayout.LayoutParams(0,dp(42),1));sync.setOnCheckedChangeListener((v,b)->{checkpoint();f.delaySync=b;save(false);refresh();});ping.setOnCheckedChangeListener((v,b)->{checkpoint();f.pingPong=b;save(false);});if(f.delaySync)knobs(box,new Knob("LEFT",.125,2,"beats",new Value(){public double get(){return f.leftBeats;}public void set(double v){f.leftBeats=v;}}),new Knob("RIGHT",.125,2,"beats",new Value(){public double get(){return f.rightBeats;}public void set(double v){f.rightBeats=v;}}));else knobs(box,new Knob("LEFT",10,2000,"ms",new Value(){public double get(){return f.leftMs;}public void set(double v){f.leftMs=v;}}),new Knob("RIGHT",10,2000,"ms",new Value(){public double get(){return f.rightMs;}public void set(double v){f.rightMs=v;}}));knobs(box,new Knob("FEEDBACK",0,.85,"%",new Value(){public double get(){return f.delayFeedback;}public void set(double v){f.delayFeedback=v;}}),new Knob("WIDTH",0,1,"%",new Value(){public double get(){return f.delayWidth;}public void set(double v){f.delayWidth=v;}}),new Knob("WET MIX",0,.6,"%",new Value(){public double get(){return f.delayMix;}public void set(double v){f.delayMix=v;}}));}
 void setupMidi(){liveMidi=new LiveMidi(engine,synthConfig);midi=new MidiController(this,handler,new MidiController.Listener(){public void status(String message){if(dead)return;toast(message);if(midi.connected){if(midiForeground&&requestAudioFocus())liveMidi.start();}else{liveMidi.stop();if(midiTake!=null)finishMidiTake();}}public void event(int status,int a,int b){event(status,a,b,0);}public void event(int status,int a,int b,long stamp){final long nanos=stamp>0&&stamp<=System.nanoTime()+5_000_000L?stamp:System.nanoTime();if(dead||!midiForeground||!midi.connected)return;if(pro.midiControl(status,a,b))return;if((status&240)==192)handler.post(()->{if(!dead&&midiForeground)synthConfig=Synth.factory(a%Synth.NAMES.length);});if(liveMidi.running){liveMidi.voices.message(status,a,b);MidiTake take=midiTake;if(take!=null)take.add(status,a,b,nanos);}else handler.post(()->{if(!dead&&midiForeground&&requestAudioFocus()){liveMidi.start();liveMidi.voices.message(status,a,b);MidiTake take=midiTake;if(take!=null)take.add(status,a,b,nanos);}});}});}
 void midiDialog(){if(!canEdit())return;LinearLayout box=column();box.setPadding(dp(16),dp(8),dp(16),dp(8));box.addView(label("USB MIDI: connect a compliant controller using USB OTG. Paired Bluetooth MIDI devices can also be opened. Controller audio is not imported; note, velocity, sustain, program and ±2-semitone pitch-bend messages drive the built-in synth.",12,DIM,false));box.addView(label("Status: "+(midi.connected?midi.name:"not connected"),13,TEXT,true));box.addView(label("Patch: "+Synth.NAMES[synthConfig.patch]+" · 16-voice monitor",12,DIM,false));Button usb=button("Choose connected MIDI device",()->chooseMidiDevice());box.addView(usb,new LinearLayout.LayoutParams(-1,dp(44)));box.addView(button("Open paired Bluetooth MIDI device",()->pairedBluetoothMidi()),new LinearLayout.LayoutParams(-1,dp(44)));box.addView(button("Change synth patch / envelope",()->synthDialog()),new LinearLayout.LayoutParams(-1,dp(44)));box.addView(button("Disconnect / all notes off",()->{liveMidi.stop();midi.close();}),new LinearLayout.LayoutParams(-1,dp(44)));new AlertDialog.Builder(this).setTitle("MIDI controller input").setView(box).setNegativeButton("Close",null).setPositiveButton("Record MIDI to track",(d,w)->startMidiTake()).show();}
 void chooseMidiDevice(){android.media.midi.MidiDeviceInfo[] devices=midi.devices();ArrayList<android.media.midi.MidiDeviceInfo> infos=new ArrayList<>();ArrayList<Integer> ports=new ArrayList<>();ArrayList<String> names=new ArrayList<>();for(android.media.midi.MidiDeviceInfo info:devices)for(android.media.midi.MidiDeviceInfo.PortInfo port:info.getPorts())if(port.getType()==android.media.midi.MidiDeviceInfo.PortInfo.TYPE_OUTPUT){String label=info.getProperties().getString(android.media.midi.MidiDeviceInfo.PROPERTY_NAME,"MIDI controller")+" / "+(port.getName().isEmpty()?"port "+port.getPortNumber():port.getName());infos.add(info);ports.add(port.getPortNumber());names.add(label);}if(names.isEmpty()){toast("No MIDI note-output device found. Connect the controller with USB OTG, or open a paired Bluetooth MIDI device.");return;}new AlertDialog.Builder(this).setTitle("Controller input port").setItems(names.toArray(new String[0]),(d,i)->midi.open(infos.get(i),ports.get(i),names.get(i))).setNegativeButton("Cancel",null).show();}
 void pairedBluetoothMidi(){if(Build.VERSION.SDK_INT>=31&&checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.BLUETOOTH_CONNECT},51);return;}try{android.bluetooth.BluetoothManager manager=(android.bluetooth.BluetoothManager)getSystemService(BLUETOOTH_SERVICE);android.bluetooth.BluetoothAdapter adapter=manager==null?null:manager.getAdapter();if(adapter==null){toast("Bluetooth is unavailable.");return;}ArrayList<android.bluetooth.BluetoothDevice> devices=new ArrayList<>(adapter.getBondedDevices());String[] names=new String[devices.size()];for(int i=0;i<names.length;i++){String name=devices.get(i).getName();names[i]=name==null?"Paired Bluetooth device":name;}if(names.length==0){new AlertDialog.Builder(this).setTitle("Pair your MIDI controller first").setMessage("Pair the controller in Android Bluetooth settings, then return and choose it here. Only Bluetooth MIDI-compatible devices can send MIDI notes.").setPositiveButton("Bluetooth settings",(d,w)->startActivity(new Intent(android.provider.Settings.ACTION_BLUETOOTH_SETTINGS))).setNegativeButton("Cancel",null).show();return;}new AlertDialog.Builder(this).setTitle("Choose paired MIDI controller").setItems(names,(d,i)->midi.openBluetooth(devices.get(i))).setNegativeButton("Cancel",null).show();}catch(Exception e){error("Bluetooth MIDI",e.getMessage());}}
 void startMidiTake(){startMidiTake(false);}void startMidiTake(boolean touch){startCountedMidiTake(touch,4);}
 void startCountedMidiTake(boolean touch,int beats){
  if(!canEdit()||!requestAudioFocus())return;
  engine.pause();long at=CountIn.target(engine.position,engine.loop,TakeBounds.loopStart(session),TakeBounds.loopEnd(session));
  if(at>=Core.MAX_FRAMES){toast("Move the cursor before the project limit.");return;}
  engine.position=at;startMidiTakeAt(touch,at,at,beats);
 }
 Core.Track performanceTrack(MidiTake take,String name,Core.Track fallback){
  if(!"Touch performance".equals(name))return fallback;
  String instrument=take.samplePack==null?Synth.NAMES[Math.max(0,Math.min(Synth.NAMES.length-1,take.config.patch))]:take.samplePack.name;
  return new Core.Track("Play It · "+instrument,COLORS[session.tracks.size()%COLORS.length]);
 }
 void startMidiTakeAt(boolean touch,long scheduledFrame,long projectStart){startMidiTakeAt(touch,scheduledFrame,projectStart,0);}
 void startMidiTakeAt(boolean touch,long scheduledFrame,long projectStart,int countBeats){
 if(!canEdit())return;if(touch&&session.tracks.size()>=Core.MAX_TRACKS){toast("No free track for this Play It take.");return;}if(!touch&&recordTarget()==null){toast("Select a track before recording MIDI.");return;}if(!touch&&!midi.connected){toast("Connect a MIDI controller first.");return;}if(!requestAudioFocus())return;
 checkpoint();midiTrack=recordTarget();liveMidi.voices.setConfig(synthConfig);liveMidi.voices.setSamplePack(selectedSampleInstrument);liveMidi.voices.silence();liveMidi.start();
 engine.recording=true;
 if(!engine.playing)engine.playCounted(session,countBeats); // Pre-roll holds the project cursor until its last click.
 if(!engine.playing){engine.recording=false;toast("The audio output is still stopping. Try recording again.");return;}
 long from=scheduledFrame>=0?scheduledFrame:engine.transportFrames;
 midiStart=projectStart>=0?projectStart:engine.position;
 performanceName=touch?"Touch performance":"MIDI performance";
 MidiTake armed=new MidiTake(synthConfig,session.bpm,()->engine.transportFrames,from,selectedSampleInstrument,selectedSampleInstrumentId);
 long stop=engine.loop?TakeBounds.loopEnd(session):Core.MAX_FRAMES;
 armed.clock=engine::heardAt; // notes land where the musician heard the song, not where the UI saw them
 armed.limitTo((int)Math.max(1,stop-midiStart));if(engine.loop)armed.projectStop=stop;midiTake=armed;
 engine.recording=true;
 toast(scheduledFrame>=0?"Get ready. The song starts after the count-in.":"Recording. The backing beat keeps playing.");updateTransport();}

 void finishMidiTake(){
  final MidiTake recorded=midiTake;if(recorded==null)return;boolean cancelled=recorded.pending();recorded.finish();midiTake=null;engine.recording=false;liveMidi.voices.silence();
  if(cancelled){engine.recording=false;engine.pause();toast("Count-in cancelled; no take added.");return;}
  final Core.Track target=midiTrack;final long start=midiStart;final Core.Session project=session;final String takeName=performanceName;
  final boolean touchPerformance="Touch performance".equals(takeName);
  final MidiTake take=TakeBounds.fit(recorded,start,project,recordQuantize(),getPreferences(MODE_PRIVATE).getBoolean("extendToBar",true));
  if(pro.liveMidiTake(take,target,start,takeName))return;
  final long clipStart=start;final Core.Track destination=performanceTrack(take,takeName,target);
  busy("Printing your performance and saving its MIDI source…",()->{
   File audio=new File(project.directory,UUID.randomUUID()+".pcm"),notes=new File(project.directory,UUID.randomUUID()+".mid");boolean success=false;
   try{
    try(AudioIO.Writer writer=new AudioIO.Writer(audio)){take.print((l,r)->writer.sample(l,r));}
    try(OutputStream out=new FileOutputStream(notes)){take.writeMidi(out);}
    Core.Clip printed=new Core.Clip(takeName,new AudioIO.Disk(audio),audio.getName(),clipStart);
    printed.length=(int)Math.min(Math.min(printed.length,take.frames),Core.MAX_FRAMES-clipStart);printed.midiFile=notes.getName();
    if(printed.length<=0)throw new IOException("Move the cursor before the project limit.");
    success=true;
    runOnUiThread(()->{
     if(session!=project){audio.delete();notes.delete();toast("Project changed; performance was not saved.");return;}
     if(destination!=target)project.tracks.add(destination);
     destination.clips.add(printed);selected=destination;clip=printed;screen="ARRANGE";save(false);refresh();
     toast(touchPerformance?"Play It take saved to its own instrument track, "+(recordQuantize()>0?"quantized to 1/"+(4*recordQuantize())+" notes.":"timed exactly as you played it."):"Performance saved on its track. Undo is available; the original notes can be exported from the project menu.");
    });
   }finally{if(!success){audio.delete();notes.delete();}}
  });
 }
