 void clipProperties(Core.Clip c){if(!canEdit())return;LinearLayout box=column();box.setPadding(dp(20),dp(5),dp(20),dp(10));TextView intro=label(c.name+"\nNon-destructive gain and edge fades.",13,DIM,false);box.addView(intro);EditText gain=numberField(box,"CLIP GAIN  /  −24 TO +24 dB",String.format(Locale.US,"%.2f",20*Math.log10(c.gain)));EditText in=numberField(box,"FADE IN  /  milliseconds",String.format(Locale.US,"%.2f",c.fadeIn*1000.0/Core.RATE));EditText out=numberField(box,"FADE OUT  /  milliseconds",String.format(Locale.US,"%.2f",c.fadeOut*1000.0/Core.RATE));new AlertDialog.Builder(this).setTitle("Region processing").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Apply",(d,w)->{try{double db=Double.parseDouble(gain.getText().toString()),inMs=Double.parseDouble(in.getText().toString()),outMs=Double.parseDouble(out.getText().toString());if(!Double.isFinite(db)||!Double.isFinite(inMs)||!Double.isFinite(outMs)||db< -24||db>24||inMs<0||outMs<0||inMs>600000||outMs>600000)throw new Exception();int fi=(int)Math.round(inMs*Core.RATE/1000),fo=(int)Math.round(outMs*Core.RATE/1000);boolean changed=fi!=c.fadeIn||fo!=c.fadeOut;if(changed&&(fi>c.length||fo>c.length))throw new Exception();engine.pause();checkpoint();c.gain=Math.pow(10,db/20);if(changed){c.fadeIn=fi;c.fadeOut=fo;c.envelopeOffset=0;c.envelopeLength=c.length;}save(false);refresh();}catch(Exception e){toast("Use gain from −24 to +24 dB, and fades no longer than the region.");}}).show();}
