   // Input / instrument slot with channel mode (mono ◯ / stereo ◯◯)
   if(master)slotBox(c,in,yInput(),wid,dp(20),"Stereo Out",true,0xffb8c6d0);
   else{pill(c,t.mono?"◯":"◯◯",in,yInput(),dp(26),dp(20),true,0xff9fb0bb);boolean inst=instrument(t);String src=inst?instrumentLabel(t):pro.inputDevice()==null?"Input 1":fit(pro.deviceName(pro.inputDevice()),10);slotBox(c,in+dp(30),yInput(),wid-dp(30),dp(20),fit(src,11),inst,0xff9fd29b);}
