   boolean bypass=!master&&t.bypassFx;for(int k=0;k<FX_SLOTS;k++){boolean has=k<labels.size();String l=has?(k==FX_SLOTS-1&&labels.size()>FX_SLOTS?"+"+(labels.size()-FX_SLOTS+1)+" more":fit(labels.get(k),13)):k==labels.size()?"+ Audio FX":"";if(!has&&k>labels.size()){p.setColor(0xff26303a);c.drawRoundRect(in,yFx(k),in+wid,yFx(k)+dp(17),dp(4),dp(4),p);continue;}slotBox(c,in,yFx(k),wid,dp(17),l,has,bypass?0xff6b6560:0xff7fb5d9);}
   // Sends
   if(master){text(c,"no sends",cx,ySend(0)+dp(13),8,DIM,false);}
   else for(int k=0;k<SEND_SLOTS;k++){Pro.Send send=k<t.sends.size()?t.sends.get(k):null;if(send==null){if(k==t.sends.size())slotBox(c,in,ySend(k),wid,dp(17),"+ Send",false,0);else{p.setColor(0xff26303a);c.drawRoundRect(in,ySend(k),in+wid,ySend(k)+dp(17),dp(4),dp(4),p);}continue;}
    Core.Track bus=session.bus(send.bus);slotBox(c,in,ySend(k),wid-dp(22),dp(17),fit(bus==null?"Bus":bus.name,9)+(send.pre?" pre":""),true,0xffd9c27f);float kx=in+wid-dp(9),ky=ySend(k)+dp(8.5f);p.setColor(0xff1b2229);c.drawCircle(kx,ky,dp(8),p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(2));p.setColor(0xffd9c27f);c.drawArc(kx-dp(7),ky-dp(7),kx+dp(7),ky+dp(7),135,(float)(270*Math.min(1,send.level/2)),false,p);p.setStyle(Paint.Style.FILL);}
   // Output, group, automation
   String out=master?"Output 1-2":t.output==null?"Stereo Out":(session.bus(t.output)==null?"Stereo Out":fit(session.bus(t.output).name,12));slotBox(c,in,yOut(),wid,dp(19),out,true,0xffb8c6d0);
   slotBox(c,in,yGroup(),wid,dp(19),master?"":t.group==null?"Group":fit(t.group,12),!master&&t.group!=null,0xffc7a9e0);
   int am=master?(session.masterAutomation!=null&&session.masterAutomation.size()>0?1:0):t.automationMode;slotBox(c,in,yAuto(),wid,dp(19),automationName(am),am!=0,automationColor(am));
   // Track colour bar
   p.setColor(color);c.drawRoundRect(in+dp(16),yAuto()+dp(23),in+wid-dp(16),yAuto()+dp(26),dp(1),dp(1),p);
   // Pan knob
   float py=panY();if(!master){p.setColor(0xff1b2229);c.drawCircle(cx,py,dp(15),p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(3));p.setColor(0xff2f3b44);c.drawArc(cx-dp(12),py-dp(12),cx+dp(12),py+dp(12),135,270,false,p);p.setColor(0xff9fd2e0);float sweep=(float)(t.pan*135);c.drawArc(cx-dp(12),py-dp(12),cx+dp(12),py+dp(12),270,sweep,false,p);p.setStyle(Paint.Style.FILL);double ang=Math.toRadians(270+t.pan*135);p.setColor(0xffe3eaee);c.drawCircle(cx+(float)Math.cos(ang)*dp(8),py+(float)Math.sin(ang)*dp(8),dp(2.2f),p);text(c,Math.abs(t.pan)<.005?"C":(t.pan<0?"L":"R")+Math.round(Math.abs(t.pan)*64),cx,py+dp(25),8,DIM,false);}
   else{text(c,String.format(Locale.US,"GR %.1f dB",engine.reduction),cx,py+dp(4),9,0xffd7c7a3,true);}
   // Peak level display: red when the signal clipped above 0 dB, orange when above 0 dB without clipping
   float held=master?engine.peakHold:t.peakHold;boolean clip=master?engine.overloaded:held>1.12f;p.setColor(held>1?(clip?0xffd9534f:0xffe39a4a):0xff1b2229);c.drawRoundRect(in+dp(14),yPeak(),in+wid-dp(14),yPeak()+dp(15),dp(3),dp(3),p);text(c,held<=.001?"−∞":String.format(Locale.US,"%.1f",20*Math.log10(held)),cx,yPeak()+dp(11),9,held>1?0xff1d252c:TEXT,true);
   c.restore();c.save();c.clipRect(bounds);
   // Fader and level meter
   float ft=top(),fb=bottom(),rail=x+dp(48);p.setColor(0xff212c34);c.drawRoundRect(rail-dp(5),ft-dp(4),rail+dp(5),fb+dp(4),dp(5),dp(5),p);for(int tick:new int[]{6,0,-6,-12,-24,-48}){float y=gainY(Math.pow(10,tick/20.0));p.setColor(tick==0?0xffd0d9de:0xff87949d);p.setStrokeWidth(dp(tick==0?1.3f:.6f));c.drawLine(x+dp(24),y,x+dp(34),y,p);c.drawLine(x+dp(62),y,x+dp(68),y,p);text(c,(tick>0?"+":"")+tick,x+dp(15),y+dp(3),7,tick==0?TEXT:DIM,false);}
   float left=master?engine.peakLeft:t.armed&&capture!=null&&capture.running?capture.meter:t.meterL,right=master?engine.peakRight:t.armed&&capture!=null&&capture.running?capture.meter:t.meterR;meter(c,x+dp(80),ft,fb,left,held);meter(c,x+dp(89),ft,fb,right,held);
   double gain=pro.shownVolume(t);float fy=gainY(gain);p.setColor(0xff1a242c);c.drawRoundRect(rail-dp(14),fy-dp(18),rail+dp(14),fy+dp(22),dp(5),dp(5),p);p.setShader(new LinearGradient(rail-dp(13),fy-dp(18),rail+dp(13),fy+dp(18),new int[]{0xffd0d7dc,0xff939fa9,0xffaebbc4,0xff727f89},null,Shader.TileMode.CLAMP));c.drawRoundRect(rail-dp(13),fy-dp(18),rail+dp(13),fy+dp(18),dp(4),dp(4),p);p.setShader(null);p.setColor(0xff38464f);p.setStrokeWidth(dp(1));for(int k=-2;k<=2;k++){float y=fy+k*dp(5);c.drawLine(rail-dp(9),y,rail+dp(9),y,p);}p.setColor(0xff26313a);p.setStrokeWidth(dp(2));c.drawLine(rail-dp(11),fy,rail+dp(11),fy,p);
   // Volume field
   float b0=fb+dp(8);p.setColor(0xff1b2229);c.drawRoundRect(in+dp(10),b0,in+wid-dp(10),b0+dp(17),dp(4),dp(4),p);text(c,db(gain),cx,b0+dp(12.5f),10,TEXT,true);
   // Record-enable / input monitoring (output strip: Bounce / Dim)
   float r0=b0+dp(22),half=(wid-dp(6))/2;
   if(master){pill(c,"Bnce",in,r0,half,dp(22),false,0);pill(c,"Dim",in+half+dp(6),r0,half,dp(22),engine.dim,0xffe0c070);}
   else{pill(c,"R",in,r0,half,dp(22),t.armed,0xffe0635a);pill(c,"I",in+half+dp(6),r0,half,dp(22),t.inputMonitor,0xffe8a85c);}
   // Mute / solo
   float m0=r0+dp(26);if(master)pill(c,"M",in,m0,wid,dp(22),session.master<=.0001,0xff7fb5d9);else{pill(c,"M",in,m0,half,dp(22),t.mute,0xff7fb5d9);pill(c,"S",in+half+dp(6),m0,half,dp(22),t.solo,0xffe5cf6a);}
   // Name
   float n0=m0+dp(26);p.setColor(color);c.drawRoundRect(in,n0,in+wid,n0+dp(20),dp(4),dp(4),p);text(c,master?"Stereo Out":fit(t.name,13),cx,n0+dp(14),10,0xff1d252c,true);
